function majorityElement(nums: number[]): number {
  // Текущий кандидат в большинство и его «перевес» голосов
  let candidate = nums[0];
  let count = 0;

  for (const x of nums) {
    if (count === 0) {
      // Перевеса нет — новый элемент становится кандидатом
      candidate = x;
    }
    // Голос «за» своего кандидата, «против» — за чужого
    count += x === candidate ? 1 : -1;
  }

  // По условию большинство существует, значит это кандидат
  return candidate;
}

// Время: O(n) — один проход
// Память: O(1) — алгоритм голосования Бойера–Мура
